package main

import (
	"bufio"
	"fmt"
	"os"
)

func balanced(s string) bool {
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	stack := []rune{}
	for _, ch := range s {
		if open, isCloser := pairs[ch]; isCloser {
			if len(stack) == 0 || stack[len(stack)-1] != open {
				return false // nothing to close, or the wrong kind
			}
			stack = stack[:len(stack)-1]
		} else {
			stack = append(stack, ch)
		}
	}
	return len(stack) == 0 // every opener was closed
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		line := scanner.Text()
		if balanced(line) {
			fmt.Println(line, "balanced")
		} else {
			fmt.Println(line, "not balanced")
		}
	}
}

