package main

import (
	"bufio"
	"fmt"
	"os"
)

func check(s string) string {
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	stack := []rune{}
	for i, ch := range s {
		if open, isCloser := pairs[ch]; isCloser {
			if len(stack) == 0 || stack[len(stack)-1] != open {
				return fmt.Sprintf("error at %d", i+1)
			}
			stack = stack[:len(stack)-1]
		} else {
			stack = append(stack, ch)
		}
	}
	if len(stack) > 0 {
		return "unclosed"
	}
	return "ok"
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		line := scanner.Text()
		fmt.Println(line, check(line))
	}
}

