package main

import (
	"container/list"
	"fmt"
)

func main() {
	line := list.New()
	var n int
	fmt.Scan(&n)
	for ; n > 0; n-- {
		var cmd string
		fmt.Scan(&cmd)
		switch cmd {
		case "join", "vip":
			var name string
			fmt.Scan(&name)
			if cmd == "join" {
				line.PushBack(name)
			} else {
				line.PushFront(name) // cuts to the front
			}
		case "serve":
			if line.Len() > 0 {
				fmt.Println("served", line.Remove(line.Front()).(string))
			}
		case "leave":
			if line.Len() > 0 {
				fmt.Println("left", line.Remove(line.Back()).(string))
			}
		}
	}
	fmt.Print("waiting:")
	for e := line.Front(); e != nil; e = e.Next() {
		fmt.Print(" ", e.Value)
	}
	fmt.Println()
}

