package main

import (
	"container/list"
	"fmt"
)

func main() {
	deck := list.New()
	var n int
	fmt.Scan(&n)
	for ; n > 0; n-- {
		var cmd string
		fmt.Scan(&cmd)
		if cmd == "top" || cmd == "bottom" {
			var card string
			fmt.Scan(&card)
			if cmd == "top" {
				deck.PushFront(card)
			} else {
				deck.PushBack(card)
			}
			continue
		}
		if deck.Len() == 0 {
			fmt.Println("empty")
		} else if cmd == "deal" {
			fmt.Println("dealt", deck.Remove(deck.Front()).(string))
		} else {
			fmt.Println("burned", deck.Remove(deck.Back()).(string))
		}
	}
	fmt.Printf("left: %d cards\n", deck.Len())
}

