	for i, t := range temps {
		for len(window) > 0 && temps[window[len(window)-1]] >= t {
			window = window[:len(window)-1]
		}
		window = append(window, i)
		if window[0] <= i-k {
			window = window[1:]
		}
		if i >= k-1 {
			mins = append(mins, temps[window[0]])
		}
	}
	fmt.Println(mins)
}
